sys_script_email.script:
(function runMailScript(/* GlideRecord */ current, /* TemplatePrinter */ template,
          /* Optional EmailOutbound */ email, /* Optional GlideRecord */ email_action,
          /* Optional GlideRecord */ event) {

	//Sets the e-mail subject of the e-mail to "Action Required: ${hr_service"}, bilingual

	var hbu = new x_hccc_base.HoCBaseUtils();

	var hrServiceFq = hbu.getTranslatedText("sn_hr_core_service", current.getValue("hr_service"), "name", "fq");
	var hrServiceEn = current.getDisplayValue("hr_service");
	//var hrServiceEn = hbu.getTranslatedText("sn_hr_core_service", current.getValue("hr_service"), "name", "en");

	email.setSubject("Action Required: " + hrServiceEn + " / Action requise : " + hrServiceFq);



})(current, template, email, email_action, event);
